function renderMap(){if(!state.map||!state.markers||!state.flowLayer)return;state.markers.clearLayers();state.flowLayer.clearLayers();state.mapLayers=[];var marketCodes=new Set();state.tradeProducts.forEach(function(p){if(p.market_iso3)marketCodes.add(p.market_iso3)});state.tradeFlows.forEach(function(f){if(f.buyer_iso3)marketCodes.add(f.buyer_iso3);if(f.supplier_iso3)marketCodes.add(f.supplier_iso3)});state.signals.forEach(function(s){(s.author_country_iso2||[]).forEach(function(code){var c=state.countries.find(function(x){return x.iso2===code});if(c)marketCodes.add(c.iso3)})});var coords=[];state.countries.forEach(function(c){if(!marketCodes.has(c.iso3))return;var lat=finite(c.latitude),lon=finite(c.longitude);if(lat===null||lon===null||Math.abs(lat)>90||Math.abs(lon)>180)return;coords.push([lat,lon]);var marker=L.circleMarker([lat,lon],{radius:6,weight:1.5,color:document.documentElement.dataset.theme==="dark"?"#f3f6fb":"#ffffff",fillColor:"#0b8176",fillOpacity:.95});marker.bindTooltip(escapeHtml(c.name)+" ("+escapeHtml(c.iso3)+")");marker.bindPopup('<strong>'+escapeHtml(c.name)+'</strong><br><span>'+escapeHtml(c.region||"Country reference point")+'</span><br><small>Capital reference coordinates · select country for context</small>');marker.on("click",function(){renderCountryBrief(c.iso3);renderRegionExplorerDetail(c.iso3)});marker.addTo(state.markers)});var aggregated={};state.tradeFlows.forEach(function(f){var a=f.supplier_iso3,b=f.buyer_iso3;if(!a||!b)return;var key=a+"|"+b;var val=finite(f.import_value_usd)||0;if(!aggregated[key])aggregated[key]={supplier_iso3:a,buyer_iso3:b,value:0,products:0,records:[],id:"route-"+key};aggregated[key].value+=val;aggregated[key].products+=1;aggregated[key].records.push(f)});var routes=Object.values(aggregated).sort(function(a,b){return b.value-a.value});var marketFilter=$("marketFilter").value;if(marketFilter!=="all")routes=routes.filter(function(r){return r.supplier_iso3===marketFilter||r.buyer_iso3===marketFilter});if(state.mapMode==="top")routes=routes.slice(0,12);if(state.mapMode==="off")routes=[];routes.slice(0,100).forEach(function(r){var a=getCountry(r.supplier_iso3),b=getCountry(r.buyer_iso3);var lat1=finite(a.latitude),lon1=finite(a.longitude),lat2=finite(b.latitude),lon2=finite(b.longitude);if(lat1===null||lon1===null||lat2===null||lon2===null)return;var maxVal=routes.reduce(function(m,x){return Math.max(m,x.value)},1);var weight=1.5+Math.min(4,Math.log1p(r.value)/Math.max(1,Math.log1p(maxVal))*4);var line=L.polyline([[lat1,lon1],[lat2,lon2]],{color:"#a4bb45",weight:weight,opacity:.68});line.bindPopup('<strong>'+escapeHtml(a.name)+' → '+escapeHtml(b.name)+'</strong><br>'+escapeHtml(fmtMoney(r.value))+' reported imports<br>'+r.products+' product-period records<br><small>Origin partner → reporting importer</small>');line.on("click",function(){if(r.records[0])selectFlow(r.records[0]);renderCountryBrief(r.buyer_iso3)});line.addTo(state.flowLayer);state.mapLayers.push(line)});$("mapStatus").textContent=marketCodes.size+" markets in trade/research snapshot · "+state.mapLayers.length+" mapped import links";if(coords.length&&state.map.getZoom()===2){state.map.fitBounds(coords,{padding:[20,20],maxZoom:4})}}
