function visibleSignals(){var query=$("searchInput").value.trim().toLowerCase();var sector=$("sectorFilter").value;var source=$("sourceFilter").value;return state.signals.filter(function(s){var matchSector=sector==="all"||(s.sectors||[]).indexOf(sector)>=0;var matchSource=source==="all"||(s.data_sources||[]).indexOf(source)>=0;var hay=[s.title,s.summary,s.abstract,s.venue,s.publisher,(s.sectors||[]).join(" "),(s.queries||[]).join(" "), (s.authors||[]).join(" ")].join(" ").toLowerCase();return matchSector&&matchSource&&(!query||hay.indexOf(query)>=0)}).sort(function(a,b){return String(b.publication_date||"").localeCompare(String(a.publication_date||""))})}
