 var signals=countryResearchSignals(iso).slice().sort(function(a,b){return String(b.publication_date||"").localeCompare(String(a.publication_date||""))}).slice(0,6);
 var indicatorNames={gdp_usd:"GDP, current US$",gdp_per_capita_usd:"GDP per capita, current US$",population:"Population",trade_pct_gdp:"Trade (% of GDP)"};
 var indicatorCards=Object.keys(indicatorNames).map(function(key){var item=ind[key]||{};var val=finite(item.value);var display=val===null?"Not available":key==="population"?fmtNumber(val):key==="trade_pct_gdp"?val.toFixed(1)+"%":fmtMoney(val);return '<div class="region-data-tile"><span>'+escapeHtml(indicatorNames[key])+'</span><strong>'+escapeHtml(display)+'</strong><small>'+(item.year?"Year: "+escapeHtml(item.year):"No value in latest snapshot")+'</small></div>'}).join("");
 var productHtml=products.length?'<div class="region-sublist">'+products.map(function(p){return '<div class="region-data-row"><span><strong>'+escapeHtml(p.product_name||("HS "+p.product_code))+'</strong><small>HS '+escapeHtml(p.product_code||"—")+' · '+escapeHtml(p.latest_year||"Latest year unavailable")+'</small></span><b>'+escapeHtml(fmtMoney(p.latest_import_usd))+'</b></div>'}).join("")+'</div>':'<p class="region-empty-note">No product-market series are available for this country in the current trade snapshot. This does not mean trade is zero.</p>';
